'use strict';
const $=s=>document.querySelector(s);const $$=s=>Array.from(document.querySelectorAll(s));
const methods=['teacher','student','fisher','dare','pleas','soup','ours'];
const labels={teacher:'Teacher',student:'Student',fisher:'Fisher',dare:'DARE',pleas:'PLeaS',soup:'Diffusion Soup',ours:'Our merge'};
$$('[data-grid]').forEach(el=>{for(let i=0;i<9;i++){const im=document.createElement('img');im.src=`assets/portrait-${el.dataset.grid}-${i}.webp`;im.alt=`${labels[el.dataset.grid]} portrait generation ${i+1}`;el.append(im)}});
let topic='portrait',sample=0,timer=null;
function updateSamples(){['teacher','student','ours'].forEach(method=>{const im=$(`#sample-${method}`);im.src=`assets/${topic}-${method}-${sample}.webp`;im.alt=`${labels[method]} ${topic==='portrait'?'freckled portrait':'refrigerator'} generation ${sample+1}`});$('#sample-count').textContent=`SAMPLE ${String(sample+1).padStart(2,'0')} / 09`;$('#teacher-steps').textContent=topic==='portrait'?'50 steps':'28 steps';$('#prompt').textContent=topic==='portrait'?'“A photo of a young woman with freckles”':'“A photo of a refrigerator”';$('#baselines').replaceChildren();['teacher','student','pleas','soup','ours'].forEach(m=>{const f=document.createElement('figure');const im=document.createElement('img');im.src=`assets/${topic}-${m}.webp`;im.alt=`Nine ${topic} generations from ${labels[m]}`;const c=document.createElement('figcaption');c.textContent=labels[m];f.append(im,c);$('#baselines').append(f)})}
function activate(selector,button){$$(selector).forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))})}
$$('[data-topic]').forEach(b=>b.addEventListener('click',()=>{topic=b.dataset.topic;sample=0;activate('[data-topic]',b);updateSamples()}));
$('#prev').onclick=()=>{sample=(sample+8)%9;updateSamples()};$('#next').onclick=()=>{sample=(sample+1)%9;updateSamples()};
function stop(){clearInterval(timer);timer=null;$('#play').textContent='▶ Play';$('#play').setAttribute('aria-pressed','false')}
$('#play').onclick=()=>{if(timer){stop();return}timer=setInterval(()=>{sample=(sample+1)%9;updateSamples()},1600);$('#play').textContent='Ⅱ Pause';$('#play').setAttribute('aria-pressed','true')};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});updateSamples();
const steps=[['LOW-RANK WEIGHT SPACE','Instead of one global interpolation coefficient, assign a separate coefficient to each singular-vector pair. This makes merging more expressive while keeping its representation compact.','W<sub>merged</sub> = W<sub>student</sub> + Σ<sub>k</sub> τ<sub>k</sub> ã<sub>k</sub>b̃<sub>k</sub><sup>⊤</sup>'],['A POLICY OVER COEFFICIENTS','Sample coefficient logits from learned Gaussian distributions, then apply a sigmoid. Each sampled coefficient vector creates a candidate merged model, evaluated with multiple seeds and the same calibration prompt.','z<sub>k</sub> ∼ N(μ<sub>k</sub>, σ<sub>k</sub>²)<br>τ<sub>k</sub> = sigmoid(z<sub>k</sub>)'],['QUALITY + DIVERSITY','Aesthetic quality and pairwise DINOv2 embedding distances provide rewards. GRPO updates the coefficient policy using relative rewards across candidate merges, without differentiating through image sampling.','R = ū<sub>quality</sub> + λ<sub>div</sub> · ū<sub>diversity</sub>']];
$$('[data-step]').forEach(b=>b.onclick=()=>{activate('[data-step]',b);const s=steps[Number(b.dataset.step)];$('#detail-label').textContent=s[0];$('#detail-text').textContent=s[1];$('#formula').innerHTML=s[2]});
const data={sdxl:[['SDXL',50,.2884,.1462,4.2931,.3801,20.279,.8160,22.821],['SDXL-turbo',4,.1064,.0918,4.2414,.4283,26.181,.5506,22.464],['Fisher',4,.0539,.1045,3.4303,.2998,48.278,.2677,21.865],['DARE',4,.2286,.1966,1.3818,.1946,150.27,.2190,18.507],['PLeaS',4,.1958,.1216,3.4379,.3355,28.397,.5511,22.128],['Diffusion Soup',4,.1806,.1182,4.0877,.4179,26.277,.6968,22.633],['Ours',4,.1962,.1205,4.3483,.4276,25.335,.7964,23.103]],sd3:[['SD3.5-L',28,.2600,.1202,4.3438,.3339,21.016,1.0457,23.059],['SD3.5-L-turbo',4,.2215,.1038,4.2090,.3555,28.283,.9071,22.932],['Fisher',4,.1967,.1327,2.7255,.2471,35.325,.3740,22.000],['DARE',4,.1965,.1851,1.8403,.1452,78.996,-.9952,20.508],['PLeaS',4,.0767,.1484,2.5242,.3114,250.22,-1.8607,18.841],['Diffusion Soup',4,.2118,.1484,3.2049,.3030,29.255,.5637,22.310],['Ours',4,.2656,.1045,4.2796,.3608,25.819,.9513,23.040]]};
function renderResults(model){const rows=data[model];$('#results-body').replaceChildren();$('#chart').replaceChildren();rows.forEach((r,i)=>{const tr=document.createElement('tr');if(i===6)tr.className='our-result';r.forEach((v,j)=>{const td=document.createElement('td');td.textContent=j<2?v:Number(v).toFixed(j===6||j===8?3:4);tr.append(td)});$('#results-body').append(tr);const bar=document.createElement('div');bar.className=`bar-row ${i===6?'highlight':i===0?'teacher':''}`;bar.innerHTML=`<span>${r[0]}</span><div class="bar-track"><div class="bar" style="width:${r[2]/.32*100}%"></div></div><b>${r[2].toFixed(4)}</b>`;$('#chart').append(bar)});$('#gain').innerHTML=`+${((rows[6][2]/rows[1][2]-1)*100).toFixed(1)}<span>%</span>`;$('#quality-gain').textContent=`${rows[1][4].toFixed(4)} → ${rows[6][4].toFixed(4)}`}
$$('[data-model]').forEach(b=>b.onclick=()=>{activate('[data-model]',b);renderResults(b.dataset.model)});renderResults('sdxl');
const prompts={baseball:'a baseball player bunting at a baseball on a field.',redhead:'A Woman with bright red hair sitting in front of a table.',bird:'A small white bird standing on top of a pond of water.',kite:'A child flies a kite in an urban setting.'};
function renderQuality(t){$('#quality-grid').replaceChildren();methods.forEach(m=>{const f=document.createElement('figure');const im=document.createElement('img');im.src=`assets/${t}-${m}.webp`;im.alt=`${labels[m]}: ${prompts[t]}`;im.loading='lazy';const c=document.createElement('figcaption');c.textContent=labels[m];f.append(im,c);$('#quality-grid').append(f)});$('#quality-prompt').textContent=`“${prompts[t]}”`}
$$('[data-quality]').forEach(b=>b.onclick=()=>{activate('[data-quality]',b);renderQuality(b.dataset.quality)});renderQuality('baseball');
$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#bibtex').textContent);$('#copy').textContent='Copied ✓';$('#copy-status').textContent='BibTeX copied to clipboard.';setTimeout(()=>$('#copy').textContent='Copy BibTeX ↗',2200)}catch{const r=document.createRange();r.selectNodeContents($('#bibtex'));const selection=window.getSelection();selection.removeAllRanges();selection.addRange(r);$('#copy-status').textContent='Citation selected. Use your device’s copy command.';$('#copy').textContent='Selected — copy manually'}};
$$('[data-lightbox]').forEach(b=>b.onclick=()=>{$('#lightbox-img').src=b.dataset.lightbox;$('#lightbox-caption').textContent=b.dataset.caption;$('#lightbox').showModal()});$('#close-lightbox').onclick=()=>$('#lightbox').close();$('#lightbox').onclick=e=>{if(e.target===$('#lightbox')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};
